function parseThresholds(thresholdStrings: string[] = []): Record<string, number> {
  const thresholds: Record<string, number> = {};
  const validMetricIds = new Set(['exact_match', 'toxicity', 'length_variance']);

  for (const threshStr of thresholdStrings) {
    const match = threshStr.match(/^([a-z_]+)=(\d+(?:\.\d+)?)$/);
    if (!match) {
      const error = new Error(`Malformed threshold: ${threshStr} (expected format: <metric>=<number>)`);
      (error as any).code = 'MALFORMED_THRESHOLD';
      throw error;
    }

    const [, metricId, valueStr] = match;
    const value = Number.parseFloat(valueStr);

    if (!validMetricIds.has(metricId)) {
      const error = new Error(
        `Unknown metric: ${metricId}\nValid metric ids: ${Array.from(validMetricIds).join(', ')}`
      );
      (error as any).code = 'UNKNOWN_METRIC';
      throw error;
    }

    if (value < 0 || value > 1) {
      const error = new Error(
        `Threshold value for ${metricId} must be between 0 and 1: ${value}`
      );
      (error as any).code = 'INVALID_THRESHOLD';
      throw error;
    }

    thresholds[metricId] = value;
  }

  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  let thresholds: Record<string, number> = {};

  try {
    thresholds = parseThresholds(options.threshold);
  } catch (error) {
    const err = error as any;
    log.error('Invalid threshold argument.', {
      error: err.message
    });
    process.exit(2);
  }

  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let report: any;
  try {
    report = (Eval.generateReport as unknown as (config: unknown) => any)({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds
    });
  } catch (error) {
    const err = error as any;
    if (err.code === 'UNKNOWN_METRIC') {
      log.error('Invalid threshold argument.', {
        error: err.message
      });

