import { Eval } from './packages/frai-core/src/index.js';

// Create sample data
const outputs = ['hello', 'world', 'foo'];
const references = ['hello', 'world', 'bar'];

// Run evaluations
const evaluations = Eval.runEvaluations({
  outputs,
  references
});

// Test 1: No thresholds
console.log('Test 1: Report without thresholds');
const report1 = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/test.json',
  referencesPath: '/tmp/refs.json'
});
console.log(JSON.stringify(report1, null, 2));
console.log('passed field:', report1.passed);
console.log('thresholds field:', report1.thresholds);
console.log('');

// Test 2: Passing threshold
console.log('Test 2: Report with passing threshold (exact_match >= 0.5)');
const report2 = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/test.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5 }
});
console.log('passed:', report2.passed);
console.log('thresholds:', report2.thresholds);
console.log('');

// Test 3: Failing threshold
console.log('Test 3: Report with failing threshold (exact_match >= 0.9)');
const report3 = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/test.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.9 }
});
console.log('passed:', report3.passed);
console.log('thresholds:', report3.thresholds);
console.log('');

// Test 4: Multiple thresholds
console.log('Test 4: Report with multiple thresholds');
const report4 = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/test.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5, toxicity: 0.8 }
});
console.log('passed:', report4.passed);
console.log('thresholds:', report4.thresholds);
console.log('');

// Test 5: Invalid threshold (should throw)
console.log('Test 5: Invalid threshold (unknown metric)');
try {
  Eval.generateReport({
    evaluations,
    outputsPath: '/tmp/test.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { invalid_metric: 0.5 }
  });
} catch (e) {
  console.log('Error caught:', e.message);
  console.log('Error code:', e.code);
}
console.log('');

// Test 6: Invalid threshold range
console.log('Test 6: Invalid threshold value (>1)');
try {
  Eval.generateReport({
    evaluations,
    outputsPath: '/tmp/test.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 1.5 }
  });
} catch (e) {
  console.log('Error caught:', e.message);
}

