#!/usr/bin/env node
/**
 * Integration test for threshold feature
 */

import fs from 'fs';
import os from 'os';
import path from 'path';
import { Eval } from './packages/frai-core/src/index.js';

const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-threshold-test-'));

try {
  // Create test data
  const outputsPath = path.join(tmpDir, 'outputs.json');
  const referencesPath = path.join(tmpDir, 'references.json');

  fs.writeFileSync(outputsPath, JSON.stringify(['hello', 'world', 'foo']));
  fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world', 'bar']));

  console.log('Test 1: Load dataset');
  const dataset = Eval.loadDataset({ outputsPath, referencesPath });
  console.log('✓ Dataset loaded:', dataset.outputs);

  console.log('\nTest 2: Run evaluations');
  const evaluations = Eval.runEvaluations({
    outputs: dataset.outputs,
    references: dataset.references
  });
  console.log('✓ Evaluations completed');
  const exactMatchMetric = evaluations.find(m => m.id === 'exact_match');
  console.log(`  - exact_match score: ${exactMatchMetric.score}`);

  console.log('\nTest 3: Generate report without thresholds');
  const report1 = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath
  });
  console.log('✓ Report generated (no thresholds)');
  console.log(`  - Report has passed field: ${report1.passed !== undefined}`);
  console.log(`  - Report has thresholds field: ${report1.thresholds !== undefined}`);

  console.log('\nTest 4: Generate report with passing threshold');
  const report2 = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: { exact_match: 0.5 }
  });
  console.log('✓ Report generated with threshold');
  console.log(`  - Report passed: ${report2.passed}`);
  console.log(`  - Threshold results: ${JSON.stringify(report2.thresholds)}`);

  console.log('\nTest 5: Generate report with failing threshold');
  const report3 = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: { exact_match: 0.9 }
  });
  console.log('✓ Report generated with threshold');
  console.log(`  - Report passed: ${report3.passed}`);
  console.log(`  - Threshold: ${JSON.stringify(report3.thresholds[0])}`);

  console.log('\nTest 6: Write JSON report with thresholds');
  const reportPath = path.join(tmpDir, 'report.json');
  const written = Eval.writeReport({
    report: report2,
    format: 'json',
    reportPath
  });
  const content = fs.readFileSync(written, 'utf8');
  const parsed = JSON.parse(content);
  console.log('✓ JSON report written');
  console.log(`  - Has passed: ${parsed.passed !== undefined}`);
  console.log(`  - Has thresholds: ${parsed.thresholds !== undefined}`);

  console.log('\nTest 7: Write Markdown report with thresholds');
  const mdReportPath = path.join(tmpDir, 'report.md');
  const mdWritten = Eval.writeReport({
    report: report2,
    format: 'markdown',
    reportPath: mdReportPath
  });
  const mdContent = fs.readFileSync(mdWritten, 'utf8');
  console.log('✓ Markdown report written');
  console.log(`  - Has Thresholds section: ${mdContent.includes('## Thresholds')}`);
  console.log(`  - Has PASS status: ${mdContent.includes('✓ PASS')}`);

  console.log('\nTest 8: Invalid threshold (unknown metric)');
  try {
    Eval.generateReport({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds: { unknown_metric: 0.5 }
    });
    console.log('✗ Should have thrown error');
  } catch (e) {
    console.log('✓ Error thrown as expected');
    console.log(`  - Error code: ${e.code}`);
    console.log(`  - Valid metrics: ${e.validMetricIds.join(', ')}`);
  }

  console.log('\nTest 9: Invalid threshold (value > 1)');
  try {
    Eval.generateReport({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds: { exact_match: 1.5 }
    });
    console.log('✗ Should have thrown error');
  } catch (e) {
    console.log('✓ Error thrown as expected');
    console.log(`  - Error code: ${e.code}`);
  }

  console.log('\n✓ All tests passed!');
} finally {
  fs.rmSync(tmpDir, { recursive: true, force: true });
}

